import itertools

def is_kawaii(seq):
    elements = set(seq)
    max_val = max(seq)
    # Condition: if k in seq, then k-1 in seq
    for k in range(2, max_val + 1):
        if k in elements and k-1 not in elements:
            return False
    # Condition: first occurrence of k-1 comes before last occurrence of k
    for k in range(2, max_val + 1):
        if k in elements:
            first_k_minus_1 = seq.index(k-1)
            last_k = len(seq) - 1 - seq[::-1].index(k)
            if not (first_k_minus_1 < last_k):
                return False
    return True

def count_kawaii(n):
    count = 0
    # The elements must be from {1, 2, ..., n}
    for seq in itertools.product(range(1, n + 1), repeat=n):
        if is_kawaii(seq):
            count += 1
    return count

for n in range(1, 7):
    print(f"n={n}: {count_kawaii(n)}")

