def count_exact_kawaii(n, m):
    from itertools import product
    count = 0
    for seq in product(range(1, m + 1), repeat=n):
        if set(seq) == set(range(1, m + 1)):
            # check if kawaii
            is_k = True
            for k in range(2, m + 1):
                # k-1 must be in seq (already true since set(seq) is {1..m})
                first_k_minus_1 = seq.index(k-1)
                last_k = len(seq) - 1 - seq[::-1].index(k)
                if not (first_k_minus_1 < last_k):
                    is_k = False
                    break
            if is_k:
                count += 1
    return count

